[1225502] = { "Тривкість", "Ваші класові здібності, які надають усім учасникам групи чи рейду тривале посилення характеристик, діють на {1}% довше, а ефекти від відпочинку в таборі тривають на {2}% довше.#members last {1}%#camp last {2}%", en="Permanence" },
[1225503] = { "Економія реагентів", "Ваші класові здібності більше не потребують реагентів, які можна придбати в торговців.", en="Reagent Economy" },
[1317256] = { "Невідомо", "Буде додано в одному з наступних оновлень.", en="Unknown" },

