[17481] = { "Смертобіг Рівендера", "Викликає та відпускає коня барона Рівендера. Це дуже швидка верхова тварина.", "Швидкість руху збільшено на {1}%.#by {1}%", en="Rivendare's Deathcharger" },

-- Professions
[2366] = { "Травництво", "Основи збирання трав з кущів й інших рослин для використання в алхімії. Дозволяє розвивати навичку травництва до 75 рівня.", en="Herbalism" },
[2368] = { "Травництво", "Дозволяє знаходити і збирати складніші для збору трави та розвивати навичку травництва до 150 рівня.", en="Herbalism" },
[3570] = { "Травництво", "Дозволяє знаходити і збирати складніші для збору трави та розвивати навичку травництва до 225 рівня.", en="Herbalism" },
[11479] = { "Трансмутація: Залізо у золото", "Перетворює злиток заліза на злиток золота.\n\nЦю малу трансмутацію можна виконувати лише раз на годину.", en="Transmute: Iron to Gold" },
[11480] = { "Трансмутація: Мітрил у ясносрібло", "Перетворює злиток мітрилу на злиток ясносрібла.\n\nЦю малу трансмутацію можна виконувати лише раз на годину.", en="Transmute: Mithril to Truesilver" },
[11993] = { "Травництво", "Дозволяє знаходити і збирати складніші для збору трави та розвивати навичку травництва до 300 рівня.", en="Herbalism" },
[17187] = { "Трансмутація: Арканіт", "Трансмутує злиток торію та арканічний кристал у злиток арканіту.", en="Transmute: Arcanite" },
[17559] = { "Трансмутація: Повітря у вогонь", "Трансмутує сутність повітря в сутність вогню.", en="Transmute: Air to Fire" },
[17560] = { "Трансмутація: Вогонь у землю", "Трансмутує сутність вогню в сутність землі.", en="Transmute: Fire to Earth" },
[17561] = { "Трансмутація: Земля у воду", "Трансмутує сутність землі в сутність води.", en="Transmute: Earth to Water" },
[17562] = { "Трансмутація: Вода в повітря", "Трансмутує сутність води в сутність повітря.", en="Transmute: Water to Air" },
[17563] = { "Трансмутація: Невмерлість у воду", "Очищує сутність невмерлості, трансмутуючи її в сутність води.", en="Transmute: Undeath to Water" },
[17564] = { "Трансмутація: Вода у невмерлість", "Оскверняє сутність води, трансмутуючи її в сутність невмерлості.", en="Transmute: Water to Undeath" },
[17565] = { "Трансмутація: Життя у землю", "Трансмутує живу сутність у сутність землі.", en="Transmute: Life to Earth" },
[17566] = { "Трансмутація: Земля у життя", "Трансмутує сутність землі в живу сутність.", en="Transmute: Earth to Life" },
[25146] = { "Трансмутація: Первородний вогонь", "Трансмутує серце вогню у {1} первородні вогні.#into {1} Elemental", en="Transmute: Elemental Fire" },
[1226210] = { "Приладдя: телепорт", "Доповнити ваш пояс приладдям, щоб отримати наступний ефект:\n\nТелепортує вас уперед на {1} м.\n\nЦе вдосконалення постійне і його не можна зняти чи замінити.#forward {1} yds", en="Tinker: Teleport" },
[1226211] = { "Приладдя: нітроприскорювачі", "Доповнити ваш пояс приладдям, щоб отримати наступний ефект:\n\nВмикає реактивні двигуни, що збільшують вашу швидкість руху максимум на {1}% протягом щонайбільше {2} с.\n\nЦе вдосконалення постійне і його не можна зняти чи замінити.#to {1}%#to {2} sec", en="Tinker: Nitro Boosts" },
[1226212] = { "Приладдя: магнітний зміщувач", "Доповнити ваш пояс приладдям, щоб отримати наступний ефект:\n\nВикривляє магнітне поле між вами та ворожою ціллю, відкидаючи вас в протилежні сторони.\n\nМоже діяти лише на цілі, чий рівень перевищує ваш не більше ніж на {1}. Деякі цілі не можна перемістити. Цей ефект може діяти на ту саму ціль лише раз на {2} хв.\n\nЦе вдосконалення постійне і його не можна зняти чи замінити.#up to {1} level#every {2} min", en="Tinker: Magnetic Displacement" },

-- Racial
[7744] = { "Воля відречених", "Миттєво знімає всі ефекти причарування, страху та сну.", en="Will of the Forsaken" },
[20550] = { "Витримка", "Збільшує запас здоров'я на {1}% та збільшує додаткову шкоду і зцілення від критичних ефектів на {2}%.#by {1}% and#healing increased by {2}%", en="Endurance" },
[20552] = { "Культивація", "Культивувати рослину неподалік, щоб виростити її двійника, якого ви зможете зібрати без навички травництва. Кожну рослину можна культивувати лише раз.", en="Cultivation" },
[20554] = { "Берсерк", "Збільшує швидкість вимови заклять і атаки на {1}% протягом {2} с.#by {1}% for {2} sec", "Швидкість вимови заклять і атаки збільшено на {1}%.#by {1}%", en="Berserking" },
[20555] = { "Регенерація", "Швидкість регенерації здоров'я збільшено на {1}%. Крім того, регенерація здоров'я продовжується в бою зі швидкістю {2}% від звичайної.#by {1}%#addition, {2}% of", en="Regeneration" },
[20572] = { "Кривава шаленість", "Збільшує силу атаки та силу заклять на {1}% протягом {2} с.#by {1}% for {2} sec", "Силу атаки та силу заклять збільшено на {1}%.#by {1}%", en="Blood Fury" },
[20573] = { "Стійкість", "Тривалість ефектів приголомшення на вас зменшено на {1}%.#by {1}%", en="Hardiness" },
[20574] = { "Дикість", "Збільшує ймовірність завдання критичного удару всіма закляттями та здібностями на {1}%.#by {1}%", en="Savage" },
[20577] = { "Канібалізм", "При активації відновлює {1}% здоров'я та {2}% мани кожні {3} с протягом {4} с. Діє лише на трупах гуманоїдів та невмерлих в межах {5} м. Будь-який рух, дія або отримання шкоди перериває процес.#regenerates {1}% of#and {2}% of#every {3} sec#for {4} sec#within {5} y", en="Cannibalize" },
[20578] = { "Канібалізм", nil, "Відновлення {1}% здоров'я та {2}% мани кожні {3} с.#Regenerate {1}% of#and {2}% of#every {3} sec", en="Cannibalize" },
[20580] = { "Злиття з тінями", "Активуйте, щоб злитися з тінями, зменшуючи ймовірність того, що вороги помітять вас. Діє до скасування або руху. Використання цієї здібності в бою зменшує ймовірність того, що вороги атакуватимуть вас, але збільшує час відновлення до {1} хв.#to {1} min", "Злиття з тінями.", en="Shadowmeld" },
[20582] = { "Прудкість", "Ймовірність ухилення збільшено на {1}%, а швидкість руху збільшено на {2}%. Пройдисвітів та друїдів важче виявити в непомітності, ніби їхній рівень вищий на {3}.#chance increased by {1}%#speed increased by {2}%#were {3} level", en="Quickness" },
[20589] = { "Майстер втечі", "Миттєво звільняє від усіх ефектів обмеження руху й дає невразливість до них протягом {1} с.#for {1} sec", "Невразливість до ефектів обмеження руху.", en="Escape Artist" },
[20591] = { "Неосяжний розум", "Максимальний запас мани збільшено на {1}%.#by {1}%", en="Expansive Mind" },
[20593] = { "Спеціалізація на інженерії", "Ваша гномська винахідливість зменшує на {1}% ймовірність того, що інженерні пристрої дадуть збій або обернуться проти вас під час використання.#by {1}%", en="Engineering Specialization" },
[20594] = { "Кам'яна форма", "Миттєво знімає всі ефекти кровотечі, отрути та хвороб і надає невразливість до них, а також зменшує всю отриману фізичну шкоду на {1}% протягом {2} с.#by {1}% for {2} sec", "Невразливість до ефектів кровотечі, отрути та хвороб. Отриману фізичну шкоду зменшено на {1}%.#by {1}%", en="Stoneform" },
[20597] = { "Безжальність", "Збільшує ймовірність завдання критичного удару всіма закляттями та атаками на {1}%.#by {1}%", en="Ruthless" },
[1259416] = { "Хода повітрям", "Ви плавно спускаєтеся повітрям протягом {1} с, керуючи напрямком руху.#for {1} sec", "Ви крокуєте повітрям.", en="Walk on Air" },
[1259686] = { "Небесний зір", "Спробувати почерпнути силу з місця злиття стихій та отримати його благословення, що збільшить швидкість вашого руху пішки та верхи на {1}%. Діє {3} с при застосуванні біля злиття стихій і {2} хв без нього.#by {1}%#Lasts {2} sec#and {3} min", en="Skysight" },
[1259705] = { "Читання лей-лінії", "Спробувати почерпнути силу лей-лінії поблизу, що збільшить відновлення вашого здоров'я та мани на {1}%. Діє {3} хв при застосуванні біля лей-лінії і {2} с без неї.#by {1}%#Lasts {2} sec#and {3} min", en="Read Leyline" },
[1259707] = { "Знання стихій", "Шкоду елементалям збільшено на {1}%.#by {1}%", en="Elemental Insight" },
[1259710] = { "Благословення вітру", "Збільшує швидкість ближнього та дальнього бою, а також швидкість вимови заклять на {1}%.#by {1}%", en="Wind Blessed" },
[1259718] = { "Воля до виживання", "Миттєво знімає всі ефекти приголомшення.", en="Will to Survive" },
[1259719] = { "Лють землі", "Збільшує додаткову шкоду та зцілення від критичних ефектів на {1}%.#by {1}%", en="Earth Fury" },
[1259721] = { "Мисливець на велику здобич", "Шкоду звірам збільшено на {1}%.#increased by {1}", ref=20557, en="Big Game Hunter" },
[1259799] = { "Сяйво Елуни", "Збільшує ймовірність завдання критичного удару всіма закляттями та атаками на {1}% протягом {2} с.#by {1}% for {2} sec", "Ймовірність завдання критичного удару всіма закляттями та атаками збільшено на {1}%.#by {1}%", en="Elune's Light" },
[1259802] = { "Неосяжний розум", "Максимальний запас люті збільшено на {1}%.#by {1}%", en="Expansive Mind" },
[1259803] = { "Неосяжний розум", "Максимальний запас енергії збільшено на {1}%.#by {1}%", en="Expansive Mind" },
[1259812] = { "Еврика!", "Неперіодичні бойові здібності витрачають на {1}% менше енергії та завдають на {2}% більше шкоди.#by {1}% and#deal {2}% more", "Витрати енергії неперіодичних здібностей, що завдають шкоди, зменшено на {1}%, а шкоду збільшено на {2}%.#cost {1}% less#deal {2}% more", en="Eureka!" },
[1259813] = { "Еврика!", "Неперіодичні бойові здібності витрачають на {1}% менше люті та завдають на {2}% більше шкоди.#by {1}% and#deal {2}% more", "Витрати люті неперіодичних здібностей, що завдають шкоди, зменшено на {1}%, а шкоду збільшено на {2}%.#cost {1}% less#deal {2}% more", en="Eureka!" },
[1259817] = { "Еврика!", "Бойові здібності витрачають на {1}% менше мани та завдають на {2}% більше шкоди.#by {1}% and#deal {2}% more", "Витрати мани здібностей, що завдають шкоди, зменшено на {1}%, а шкоду збільшено на {2}%.#cost {1}% less#deal {2}% more", en="Eureka!" },
[1259821] = { "Еврика!", "Неперіодичні бойові здібності витрачають на {1}% менше мани та завдають на {2}% більше шкоди.#by {1}% and#deal {2}% more", "Витрати мани неперіодичних здібностей, що завдають шкоди, зменшено на {1}%, а шкоду збільшено на {2}%.#cost {1}% less#deal {2}% more", en="Eureka!" },
[1259823] = { "Еврика!", "Неперіодичні бойові або цілющі здібності витрачають на {1}% менше мани та спричиняють на {2}% більше шкоди та зцілення.#by {1}% and#deal {2}% more", "Витрати мани неперіодичних здібностей, що спричиняють шкоду чи зцілення, зменшено на {1}%, а шкоду та зцілення збільшено на {2}%.#cost {1}% less#deal {2}% more", en="Eureka!" },
[1259918] = { "Біг рівнинами", "Кожні {2} с руху збільшують вашу швидкість руху на {1}%, але не більше ніж на {3}%. Отримання шкоди або зупинка послаблюють цей ефект. Крім того, верхи ви рухаєтеся на {4}% швидше.#Gain {1}% increased#every {2} sec#of {3}% increase#move {4}% faster", en="Plainsrunning" },
[1260189] = { "Дотик могили", "Ваші закляття та атаки з ймовірністю {1}% викрадають здоров'я цілі в обсязі до {2}% вашого запасу здоров'я.#a {1}% chance#to {2}% of", en="Touch of the Grave" },
[1260201] = { ref=1260189 }, -- Touch of the Grave
[1260270] = { "Швидка регенерація", "Відновлює {1}% здоров'я протягом {2} с. Будь-який рух, дія або отримання шкоди скасовує ефект.#Regenerate {1}% of#over {2} sec", "Відновлення {1}% здоров'я протягом {2} с.#Regenerating {1}% of#over {2} sec", en="Rapid Regeneration" },
