[23161] = { "Виклик жахожеребця", "Викликає жахожеребця для верхової їзди.", "Швидкість руху збільшено на {1}%.#by {1}%", en="Summon Dreadsteed" },

-- World buffs
[15366] = { "Серенада піснеквіта", "Збільшує ймовірність завдання критичного удару в ближньому бою, дальньому бою та заклинаннями на {1}%, а також збільшує всі характеристики на {2} протягом {3} год.#critical by {1}% and all attributes by {2} for {3} h", "Збільшує ймовірність завдання критичного удару в ближньому бою, дальньому бою та заклинаннями на {1}%, а також збільшує всі характеристики на {2}. Не діє в рейдових підземеллях#critical by {1}% and all attributes by {2}", en="Songflower Serenade" },
[16609] = { "Благословення вождя", "Збільшує запас здоров'я на {1}, швидкість заклять та атак на {2}% і відновлює {3} мани кожні {4} с.#hitpoints by {1}#{2}% haste#{3} mana#every {4} sec", "Збільшує запас здоров'я на {1}, швидкість заклять та атак на {2}% і відновлює {3} мани кожні {4} с. Не діє в рейдових підземеллях.#hitpoints by {1}#{2}% haste#{3} mana#every {4} sec", en="Warchief's Blessing" },
[22817] = { "Лють Фенґа", "Силу атаки збільшено на {1}, а шкоду та зцілення заклять на {2}.#by {1} and#to {2}.", "Силу атаки збільшено на {1}, а шкоду та зцілення заклять на {2}. Не діє в рейдових підземеллях.#by {1} and#to {2}.", en="Fengus' Ferocity" },
